 public sealed class SliderR3:UserControl {
  readonly TrackBar bar=new TrackBar();readonly NumericUpDown number;bool changing;readonly double min,max;readonly Action<double> set;
  public SliderR3(double value,double low,double high,int decimals,Action<double> changed){min=low;max=high;set=changed;Size=new Size(310,57);number=UiR2.Number(value,(decimal)low,(decimal)high,decimals);number.Width=95;number.Location=new Point(210,0);bar.Minimum=0;bar.Maximum=1000;bar.TickStyle=TickStyle.None;bar.SetBounds(0,0,205,30);Controls.AddRange(new Control[]{bar,number,new Label{Text=low+" … "+high,AutoSize=true,Location=new Point(8,32)}});Set(value);bar.ValueChanged+=delegate{if(!changing)Update(min+(max-min)*bar.Value/1000);};number.ValueChanged+=delegate{if(!changing)Update((double)number.Value);};}
  public void Turn940(int delta){Update((double)number.Value+delta*(number.DecimalPlaces>0?.01:1));}
  protected override void OnResize(EventArgs e){base.OnResize(e);if(number==null)return;int nw=Math.Min(95,Math.Max(65,Width/3));number.SetBounds(Math.Max(0,Width-nw),0,nw,number.Height);bar.Width=Math.Max(30,Width-nw-6);}
  void Update(double value){Set(value);set((double)number.Value);}
  public void Set(double value){changing=true;number.Value=Math.Max(number.Minimum,Math.Min(number.Maximum,(decimal)value));bar.Value=(int)Math.Round(((double)number.Value-min)/Math.Max(.00001,max-min)*1000);changing=false;}
 }
 public static class BoundsR3 {
  public static double Min(EffectKind936 k){return k==EffectKind936.Zoom?-95:k==EffectKind936.Teinte?-180:k==EffectKind936.Luminosité||k==EffectKind936.Contraste||k==EffectKind936.Saturation||k==EffectKind936.Opacité||k==EffectKind936.Déplacement_X||k==EffectKind936.Déplacement_Y?-100:0;}
  public static double Max(EffectKind936 k){return k==EffectKind936.Zoom?400:k==EffectKind936.Teinte?180:k==EffectKind936.Contraste||k==EffectKind936.Saturation?300:k==EffectKind936.Opacité?0:k==EffectKind936.Pixelisation?256:k==EffectKind936.Flou?144:100;}
  public static string Label(EffectKind936 k){return k==EffectKind936.Teinte?"Variation de teinte (°)":k==EffectKind936.Pixelisation?"Taille des blocs (px)":k==EffectKind936.Flou?"Intensité du flou":k==EffectKind936.Mute?"Atténuation des FX suivants (%)":"Amplitude (%)";}
 }
