   if(e.Kind==EffectKind936.Zoom){Number("Centre X (%)",e.ZoomX,0,100,v=>e.ZoomX=v);Number("Centre Y (%)",e.ZoomY,0,100,v=>e.ZoomY=v);var b=new Button{Text="Placer le centre sur la frame…",AutoSize=true};b.Click+=async delegate{b.Enabled=false;try{var snap=Engine.Snapshot936(model);snap.Tracks[track].Fx=UiR2.Copy(draft);double time=TriggerR2.First(model,e);using(var frame=await System.Threading.Tasks.Task.Run(()=>FrameR2.Read(snap,track,time)))using(var f=new PointsR3(frame,e,false)){if(f.ShowDialog(this)==DialogResult.OK)ShowEffect();}}catch(Exception ex){status.Text=ex.Message;}finally{if(!b.IsDisposed)b.Enabled=true;}};editor.Controls.Add(b);}
   if(e.Kind>=EffectKind936.Colorisation&&e.Kind<=EffectKind936.Cycle_couleurs){ColorField("Couleur",e.ColorA,v=>e.ColorA=v);if(e.Kind==EffectKind936.Cycle_couleurs)Number("Cycle (noires)",e.CycleBeats,.0625m,64,v=>e.CycleBeats=v,4);if(e.Kind==EffectKind936.Dégradé)ColorField("Couleur de fin",e.ColorB,v=>e.ColorB=v);Number("Orientation / phase (°)",e.Angle,0,360,v=>e.Angle=v);Check("Balayage le long d’un trajet",e.Sweep,v=>{e.Sweep=v;ShowEffect();});if(e.Sweep){var b=new Button{Text="Dessiner départ → arrivée…",AutoSize=true};b.Click+=async delegate{b.Enabled=false;try{var snap=Engine.Snapshot936(model);snap.Tracks[track].Fx=UiR2.Copy(draft);using(var frame=await System.Threading.Tasks.Task.Run(()=>FrameR2.Read(snap,track,TriggerR2.First(model,e))))using(var f=new PointsR3(frame,e,true))f.ShowDialog(this);}catch(Exception ex){status.Text=ex.Message;}finally{if(!b.IsDisposed)b.Enabled=true;}};editor.Controls.Add(b);}}
  }
  void MaskFields(Effect936 e){var side=Combo(Enum.GetValues(typeof(MaskSideR3)).Cast<object>().ToArray(),e.MaskSide);side.SelectedIndexChanged+=delegate{e.MaskSide=(MaskSideR3)side.SelectedItem;};Field("Contour vers…",side);Number("Profondeur relative (%)",e.MaskDepth,0,100,v=>e.MaskDepth=v);Number("Douceur (%)",e.MaskSoftness,0,100,v=>e.MaskSoftness=v);Number("Décalage masque X (%)",e.MaskX,-100,100,v=>e.MaskX=v);Number("Décalage masque Y (%)",e.MaskY,-100,100,v=>e.MaskY=v);}
  void PresetSave(bool all){var effects=all?draft.Effects:new List<Effect936>{list.SelectedItem as Effect936};if(effects.Any(e=>e==null))throw new Exception("Choisir un effet.");using(var d=new SaveFileDialog{InitialDirectory=FoldersR2.Get("fx"),Filter="Preset FX autonome|*.snkozfx",FileName="Effets.snkozfx"})if(d.ShowDialog(this)==DialogResult.OK){FilesR3.SavePreset(model,effects,d.FileName);FoldersR2.Set("fx",Path.GetDirectoryName(d.FileName));status.Text="Preset enregistré, animations incluses.";}}
