   var start=UiR2.Number(musical?1:0,musical?1:0,(decimal)Math.Max(1,last),3);var end=UiR2.Number(last,musical?1:0,(decimal)Math.Max(1,last),3);start.SetBounds(290,25,180,27);end.SetBounds(290,65,180,27);
   var labelStart=new Label{Text=musical?"Mesure de départ":"Départ (s)",Location=new Point(15,30),Width=265};var labelEnd=new Label{Text=musical?"Fin — début de la mesure":"Fin (s)",Location=new Point(15,70),Width=265};Controls.AddRange(new Control[]{labelStart,labelEnd,start,end});
   var zero=new CheckBox{Text="Autour du zéro musical — temps signés en secondes",Location=new Point(15,105),Width=600,Checked=false};Controls.Add(zero);
   Action mode=()=>{if(zero.Checked){start.Minimum=(decimal)earliest;start.Maximum=(decimal)m.Duration;start.Value=(decimal)Math.Max(earliest,-2);end.Minimum=0;end.Maximum=(decimal)m.Duration;end.Value=(decimal)Math.Min(m.Duration,2);labelStart.Text="Départ (s) — négatif = avant musique";labelEnd.Text="Fin (s) — zéro = départ musical";}else{start.Minimum=musical?1:0;start.Maximum=(decimal)Math.Max(1,last);start.Value=musical?1:0;end.Minimum=musical?1:0;end.Maximum=(decimal)Math.Max(1,last);end.Value=end.Maximum;labelStart.Text=musical?"Mesure de départ":"Départ (s)";labelEnd.Text=musical?"Fin — début de la mesure":"Fin (s)";}};zero.CheckedChanged+=delegate{mode();};if(latency&&earliest<0)zero.Checked=true;
   var quality=new ComboBox{FormattingEnabled=true,DropDownStyle=ComboBoxStyle.DropDownList,Location=new Point(290,148),Width=180};quality.Items.AddRange(new object[]{"144p","240p","360p","540p","720p","Originale"});int[] heights={144,240,360,540,720,0};quality.SelectedIndex=Math.Max(0,Array.IndexOf(heights,Preferences936.Load().PreviewHeight));Controls.Add(quality);Controls.Add(new Label{Text="Résolution du preview",Location=new Point(15,153),Width=265});Controls.Add(new Label{Text=earliest<0?"Marge enregistrée : jusqu’à "+(-earliest).ToString("F3")+" s avant zéro.\nLa disponibilité réelle dépend de chaque source ; zones absentes en noir/silence.":"Pas de marge horodatée dans ce montage.\nLes anciennes prises restent lisibles ; aucun début brut supposé.",Location=new Point(15,192),Size=new Size(610,44)});
   var ok=new Button{Text="Lire cette zone",Location=new Point(350,267),Width=125};ok.Click+=delegate{bool seconds=zero.Checked||!musical;Origin=seconds?(double)start.Value:music.Time(((double)start.Value-1)*4);double stop=seconds?(double)end.Value:music.Time(((double)end.Value-1)*4);Origin=Math.Max(earliest,Math.Floor(Origin*30)/30);Length=Math.Min(m.Duration,stop)-Origin;if(Length<=0){MessageBox.Show(this,"La fin doit suivre le départ.");return;}HeightChoice=heights[quality.SelectedIndex];var p=Preferences936.Load();p.PreviewHeight=HeightChoice;p.Save();DialogResult=DialogResult.OK;};Controls.Add(ok);Controls.Add(new Button{Text="Annuler",Location=new Point(490,267),DialogResult=DialogResult.Cancel});
  }
